public void addRating(String user, int stars, String comment) {
 ratings.add(new Rating(user, stars, comment));
}

b) 
public long getUserCount() {
 return ratings.stream().map(Rating::getUser).distinct().count();
}

c) 
public List<String> getCommentsFromUser(String user) {
 return ratings.stream()
 .filter(r -> r.getUser().equals(user))
 .map(Rating::getComment)
 .collect(Collectors.toList());
}

d) 
public List<Rating> getRatingsSortedByStars() {
 return ratings.stream()
 .sorted(Comparator.comparingInt(Rating::getStars))
 .collect(Collectors.toList());
}

